package com.ias.finance;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static com.ias.finance.FeeGroup.*;
import static com.ias.finance.JdbcFeeGroups.*;
import static org.junit.jupiter.api.Assertions.*;

class CustomerConfirmationTest {
 JdbcFeeGroupsTest fixture;JdbcFeeGroups store;Actor customer=new Actor(1,99);Submit quote;
 @BeforeEach void setup()throws Exception{fixture=new JdbcFeeGroupsTest();fixture.setup();Access base=fixture.authority;store=new JdbcFeeGroups(fixture.source,new Access(){public void current(Actor a,Identity o,String action){base.current(a,o,action);}public void submission(Actor a,Identity o,Submit c,QuoteDetails d){base.submission(a,o,c,d);}public void approval(Actor a,Identity o,UUID id,ApprovalFact f){base.approval(a,o,id,f);}public void execution(Actor a,Identity o,UUID id){base.execution(a,o,id);}public void verifiedCost(Actor a,Identity o,CostFact f){base.verifiedCost(a,o,f);}public void customerConfirmation(Actor a,Identity o,QuoteVersion q){if(!a.equals(customer)||!fixture.allowed.get())throw new SecurityException("CURRENT_COMPANY_ADMIN_REQUIRED");}});quote=fixture.command(0,250000,200000,Set.of());store.submit(fixture.actor,fixture.owner,quote,charged(quote));}
 QuoteDetails charged(Submit c){return new QuoteDetails(true,"当前版本完整报价，等待企业管理员确认",fixture.details(c).kinds());}
 Receipt confirm(UUID op)throws Exception{return store.confirm(customer,fixture.owner,op,1,quote.applicationId(),1);}
 @Test void noInternalApprovalBeforeCustomerAndOnlyConfirmedVersionAdvancesHighWater()throws Exception{assertEquals(0,fixture.count("finance_approval_request"));assertEquals(0,fixture.count("finance_customer_confirmation"));assertThrows(IllegalStateException.class,()->store.approved(fixture.actor,fixture.owner,UUID.randomUUID(),1,quote.applicationId(),new ApprovalFact(UUID.randomUUID(),true,true)));assertEquals(0,fixture.count("finance_approval_fact"));confirm(UUID.randomUUID());assertEquals(1,fixture.count("finance_approval_request"));assertEquals(0,store.read(customer,fixture.owner).highestApprovedCents());store.approved(fixture.actor,fixture.owner,UUID.randomUUID(),2,quote.applicationId(),new ApprovalFact(UUID.randomUUID(),true,true));assertEquals(250000,store.read(customer,fixture.owner).highestApprovedCents());assertTrue(store.read(customer,fixture.owner).everRequiredFinance());}
 @Test void auditFaultRollsBackConfirmationRequestReceiptVersionAndOutbox()throws Exception{try(var c=fixture.source.getConnection();var s=c.createStatement()){s.execute("ALTER TABLE finance_audit ADD CONSTRAINT fail_confirm CHECK(action_name<>'CUSTOMER_QUOTE_CONFIRMED')");}UUID op=UUID.randomUUID();assertThrows(Exception.class,()->confirm(op));assertEquals(0,fixture.count("finance_customer_confirmation"));assertEquals(0,fixture.count("finance_approval_request"));assertEquals(2,fixture.count("finance_operation"));assertEquals(2,fixture.count("finance_outbox"));assertEquals(1,store.read(customer,fixture.owner).version());try(var c=fixture.source.getConnection();var s=c.createStatement()){s.execute("ALTER TABLE finance_audit DROP CONSTRAINT fail_confirm");}confirm(op);assertEquals(1,fixture.count("finance_customer_confirmation"));assertEquals(3,fixture.count("finance_outbox"));}
 @Test void concurrentSameUuidProducesOneConfirmationAndRequest()throws Exception{UUID op=UUID.randomUUID();try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var calls=new ArrayList<Future<Receipt>>();for(int i=0;i<6;i++)calls.add(pool.submit(()->{gate.await();return confirm(op);}));gate.countDown();Receipt one=calls.getFirst().get();for(var call:calls)assertEquals(one,call.get());}assertEquals(1,fixture.count("finance_customer_confirmation"));assertEquals(1,fixture.count("finance_approval_request"));assertEquals(2,store.read(customer,fixture.owner).version());}
 @Test void revisedQuoteRejectsOldConfirmationAndDoesNotInheritApprovalRequest()throws Exception{var replacement=fixture.command(1,180000,300000,Set.of(quote.additions().getFirst().id()));store.submit(fixture.actor,fixture.owner,replacement,charged(replacement));assertEquals("QUOTE_NOT_CURRENT",assertThrows(IllegalStateException.class,()->confirm(UUID.randomUUID())).getMessage());assertEquals(0,fixture.count("finance_approval_request"));store.confirm(customer,fixture.owner,UUID.randomUUID(),2,replacement.applicationId(),2);assertTrue(store.read(customer,fixture.owner).everRequiredFinance());assertEquals(1,fixture.count("finance_customer_confirmation"));}
 @Test void currentAdminAuthorityIsRequiredEvenForOriginalSuccessfulKey()throws Exception{UUID op=UUID.randomUUID();var receipt=confirm(op);assertEquals(receipt,confirm(op));fixture.allowed.set(false);assertThrows(SecurityException.class,()->confirm(op));assertThrows(SecurityException.class,()->store.operation(customer,fixture.owner,op));fixture.allowed.set(true);assertThrows(SecurityException.class,()->store.confirm(fixture.actor,fixture.owner,UUID.randomUUID(),2,quote.applicationId(),1));}
 @Test void originalReceiptQueryIsActorScopedAndPure()throws Exception{UUID op=UUID.randomUUID();var result=confirm(op);long count=fixture.count("finance_operation");assertEquals(result,store.operation(customer,fixture.owner,op));assertEquals(count,fixture.count("finance_operation"));assertThrows(SecurityException.class,()->store.operation(fixture.actor,fixture.owner,op));}
 @Test void confirmedQuoteCannotAuthorizeAfterCostsExceedFrozenBasis()throws Exception{confirm(UUID.randomUUID());store.cost(fixture.actor,fixture.owner,UUID.randomUUID(),2,new CostFact(UUID.randomUUID(),280000,null,"核实的实际成本，不自动向客户收费"));assertEquals("QUOTE_BASIS_CHANGED",assertThrows(IllegalStateException.class,()->store.approved(fixture.actor,fixture.owner,UUID.randomUUID(),3,quote.applicationId(),new ApprovalFact(UUID.randomUUID(),true,true))).getMessage());assertEquals(0,store.read(customer,fixture.owner).highestApprovedCents());}
}
